test('get returns initial value', () => {
  const s = signal(42);
  expect(s.get()).toBe(42);
});

test('set updates the value', () => {
  const s = signal(0);
  s.set(99);
  expect(s.get()).toBe(99);
});

test('subscribe is called on set', () => {
  const s = signal(0);
  const log = [];
  s.subscribe(v => log.push(v));
  s.set(1);
  s.set(2);
  expect(log).toEqual([1, 2]);
});

test('unsubscribe stops delivery', () => {
  const s = signal(0);
  const log = [];
  const unsub = s.subscribe(v => log.push(v));
  s.set(1);
  unsub();
  s.set(2);
  expect(log).toEqual([1]);
});

