solution:
export function signal(initial) {
  let value = initial;
  const subscribers = new Set();

  return {
    get() {
      return value;
    },
    set(newValue) {
      value = newValue;
      subscribers.forEach(fn => fn(value));
    },
    subscribe(fn) {
      subscribers.add(fn);
      return () => subscribers.delete(fn);
    }
  };
}
